{!REQUIRESCRIPT("/soap/ajax/24.0/apex.js")} 

try { 
var qID='{!Quote.Id}';
//alert(qID);
var result = sforce.apex.execute("AutoSyncQuoteController", "StartSyncQuote", {qID : qID}); 

if (result== 'success') {
 alert('Quote synced to opportunity');
 window.location.reload();
} else {
 alert(result)
}

}catch(err) { 
   alert('Error: ' + err); 
   window.location.reload(); 
}
